        Scanner scan = new Scanner(System.in);
        int n = scan.nextInt();
        int B = scan.nextInt();
        int[] array = new int[n];
        for (int i = 0; i < n; i++) {
            array[i] = scan.nextInt();
        }

        int[] bucketsArr = new int[101];
        int totalSum = 0;

        int evenCount = 0;
        int oddCount = 0;
        int startIdx = 0;
        int segmentCount = 0;
        int pointerIdx = 1;

        for (int i = 0; i < array.length - 1; i++) {
            if (array[i] % 2 == 0) {
                evenCount++;
            } else {
                oddCount++;
            }

            if (evenCount == oddCount) {
                int diffVal = Math.abs(array[i + 1] - array[i]);
                int maxBucketVal = getMaxBucket(bucketsArr);
                if (totalSum > B && diffVal < maxBucketVal) {
                    totalSum -= maxBucketVal;
                    bucketsArr[maxBucketVal]--;
                    bucketsArr[diffVal]++;
                    totalSum += diffVal;
                } else if (totalSum < B) {
                    totalSum += diffVal;
                    bucketsArr[diffVal]++;
                    segmentCount++;
                    startIdx = i + 1;
                }
                if (i == array.length - 2 && pointerIdx < array.length - 1) {
                    i = startIdx++;
                    evenCount = 0;
                    oddCount = 0;
                }
            }
        }
        int i = bucketsArr.length - 1;
        while (totalSum > B) {
            if (bucketsArr[i] > 0) {
                totalSum -= i;
                segmentCount--;
            } else {
                i--;
            }
        }

        System.out.println(segmentCount);
    }

    private static int getMaxBucket(int[] buckets) {
        for (int i = buckets.length - 1; i >= 0; i--) {
            if (buckets[i] > 0) {
                return i;
            }
        }
        return -1;
    }
}
