#include <iostream>
#include <vector>
#include <algorithm>
#include <cmath>

int getMaxBucket(const std::vector<int>& buckets) {
    for (int i = buckets.size() - 1; i >= 0; i--) {
        if (buckets[i] > 0) {
            return i;
        }
    }
    return -1;
}

int main() {
    int n, B;
    std::cin >> n >> B;
    std::vector<int> array(n);
    for (int i = 0; i < n; i++) {
        std::cin >> array[i];
    }

    std::vector<int> bucketsArr(101, 0);
    int totalSum = 0;

    int evenCount = 0;
    int oddCount = 0;
    int startIdx = 0;
    int segmentCount = 0;
    int pointerIdx = 1;

    for (int i = 0; i < n - 1; i++) {
        if (array[i] % 2 == 0) {
            evenCount++;
        } else {
            oddCount++;
        }

        if (evenCount == oddCount) {
            int diffVal = std::abs(array[i + 1] - array[i]);
            int maxBucketVal = getMaxBucket(bucketsArr);
            if (totalSum > B && diffVal < maxBucketVal) {
                totalSum -= maxBucketVal;
                bucketsArr[maxBucketVal]--;
                bucketsArr[diffVal]++;
                totalSum += diffVal;
            } else if (totalSum < B) {
                totalSum += diffVal;
                bucketsArr[diffVal]++;
                segmentCount++;
                startIdx = i + 1;
            }
            if (i == n - 2 && pointerIdx < n - 1) {
                i = startIdx++;
                evenCount = 0;
                oddCount = 0;
            }
        }
    }

    int i = bucketsArr.size() - 1;
    while (totalSum > B && i >= 0) {
        if (bucketsArr[i] > 0) {
            totalSum -= i;
            bucketsArr[i]--;
            if (totalSum <= B) break;
        } else {
            i--;
        }
    }

    std::cout << segmentCount << std::endl;
    return 0;
}
